<div class="ops-metrics ops-four">@foreach(['waiting'=>['Para despachar','amber'],'route'=>['Em rota','blue'],'done'=>['Entregues hoje','green'],'incidents'=>['Precisam de atenção','coral']] as $key=>[$label,$color])<div class="ops-metric {{ $color }}"><div><strong>{{ $counts[$key] }}</strong><span>{{ $label }}</span></div></div>@endforeach</div>
@unless($courierEnabled)<p class="notice">A rede de motoboys está desativada ou em encerramento. O histórico permanece disponível.</p>@endunless
<div class="ops-expedition-grid"><div class="ops-kanban">@foreach(['waiting'=>['Aguardando motoboy / coleta','amber'],'route'=>['Em rota','blue'],'done'=>['Entregues hoje','green']] as $lane=>[$label,$color])<section class="ops-lane {{ $color }}"><header><h2><i></i>{{ $label }}</h2><span>{{ $counts[$lane] }}</span></header><div class="ops-lane-cards">@forelse($lanes[$lane] as $order)@include('operations.delivery-card')@empty<p class="ops-empty">Nenhuma entrega nesta etapa.</p>@endforelse</div>{{ $lanes[$lane]->links() }}</section>@endforeach</div>
<aside class="ops-driver-panel"><h2>Motoboys <span>{{ $drivers->count() }} disponíveis</span></h2>@forelse($drivers as $driver)<article class="ops-driver available"><strong>{{ $driver->name }}</strong><small>● Disponível · Freelancer</small><small>{{ $driver->vehicle }}</small></article>@empty<p>Nenhum motoboy disponível no check-in da loja.</p>@endforelse @foreach($busy as $driver)<article class="ops-driver"><strong>{{ $driver->name }}</strong><small>{{ $driver->status==='assigned'?'Aguardando coleta':($driver->status==='returning'?'Em retorno':'Em rota') }} · Freelancer</small><small>{{ $driver->vehicle }}</small><small>{{ $driver->heartbeat_at?'Posição de '.Illuminate\Support\Carbon::parse($driver->heartbeat_at,'UTC')->timezone($store->timezone)->format('H:i:s'):'Sem posição registrada' }}</small></article>@endforeach<p class="ops-driver-tip">O motoboy precisa aceitar a oferta e registrar a coleta. Solicitar não marca o pedido como entregue.</p></aside></div>
@php($positions=$drivers->map(fn($driver)=>['name'=>$driver->name,'latitude'=>(float)$driver->latitude,'longitude'=>(float)$driver->longitude,'remaining_seconds'=>max(0,90-(now()->timestamp-Illuminate\Support\Carbon::parse($driver->heartbeat_at,'UTC')->timestamp))])->values()->all())
@foreach($busy as $driver)@if($driver->heartbeat_at&&Illuminate\Support\Carbon::parse($driver->heartbeat_at,'UTC')->gte(now()->subSeconds(90))&&is_numeric($driver->latitude)&&is_numeric($driver->longitude)&&$driver->accuracy!==null&&$driver->accuracy<=50)@php($positions[]=['name'=>$driver->name,'latitude'=>(float)$driver->latitude,'longitude'=>(float)$driver->longitude,'remaining_seconds'=>max(0,90-(now()->timestamp-Illuminate\Support\Carbon::parse($driver->heartbeat_at,'UTC')->timestamp))])@endif @endforeach
<script type="application/json" data-ops-positions>{!! Illuminate\Support\Js::encode(['store'=>$store?['name'=>$store->name,'latitude'=>(float)$store->latitude,'longitude'=>(float)$store->longitude]:null,'drivers'=>$positions,'tiles'=>config('services.delivery_map.tiles'),'timestamp'=>now()->timestamp]) !!}</script>
